    .tx_axis_mac_tlast                  (tx_axis_mac_tlast                  ),
    .tx_axis_mac_tstrb                  (tx_axis_mac_tstrb                  ),    
    .tx_axis_mac_tuser                  (tx_axis_mac_tuser                  ),
    .tx_axis_mac_tready                 (tx_axis_mac_tready                 ),
//GMII Interface
    .gm_rx_d                            (gm_rx_d_int                        ),
